//! Shared configuration types. This file is FROZEN: it defines the interface
//! between the CLI parser, the printer, the theme engine and main.rs.
//! Behavior details live in specs/*.md.

use std::path::PathBuf;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum When {
    Auto,
    Always,
    Never,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ItalicWhen {
    Always,
    Never,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NonprintableNotation {
    Unicode,
    Caret,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BinaryBehavior {
    NoPrinting,
    AsText,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PagingMode {
    Auto,
    Always,
    Never,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WrappingMode {
    Character,
    Word,
    Never,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StripAnsi {
    Auto,
    Always,
    Never,
}

/// A single line range as parsed from -r/--line-range or -H/--highlight-line.
/// Raw forms; resolved against the actual line count at print time.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LineRange {
    /// lines a..=b (1-based, inclusive)
    Range(usize, usize),
    /// first n lines (:n)
    First(usize),
    /// last n lines (-n:)
    Last(usize),
    /// from line n to end (n:)
    From(usize),
    All,
}

impl LineRange {
    /// Apply context expansion (N::C / N:M:C forms) — already baked in at parse time.
    /// Check if 1-based `line` is inside any of `ranges`, given `total` lines.
    pub fn is_contained(line: usize, total: usize, ranges: &[LineRange]) -> bool {
        ranges.iter().any(|r| match *r {
            LineRange::Range(a, b) => line >= a && line <= b,
            LineRange::First(n) => line <= n,
            LineRange::Last(n) => line > total.saturating_sub(n),
            LineRange::From(a) => line >= a,
            LineRange::All => true,
        })
    }
}

#[derive(Debug, Clone, Default)]
pub struct LineRanges(pub Vec<LineRange>);

impl LineRanges {
    pub fn is_empty(&self) -> bool {
        self.0.is_empty()
    }
    pub fn contains(&self, line: usize, total: usize) -> bool {
        self.0.is_empty() || LineRange::is_contained(line, total, &self.0)
    }
}

/// The resolved set of style components.
#[derive(Debug, Clone, Copy, Default)]
pub struct StyleComponents {
    pub numbers: bool,
    pub changes: bool,
    pub grid: bool,
    pub header_filename: bool,
    pub header_filesize: bool,
    pub rule: bool,
    pub snip: bool,
}

impl StyleComponents {
    pub fn header(&self) -> bool {
        self.header_filename || self.header_filesize
    }
    pub fn default_set() -> Self {
        StyleComponents {
            numbers: true,
            changes: true,
            grid: true,
            header_filename: true,
            header_filesize: false,
            rule: false,
            snip: true,
        }
    }
    pub fn plain() -> Self {
        StyleComponents::default()
    }
    pub fn full() -> Self {
        // 'full' = all components except 'rule' (see specs/styles.md §2)
        StyleComponents {
            numbers: true,
            changes: true,
            grid: true,
            header_filename: true,
            header_filesize: true,
            rule: false,
            snip: true,
        }
    }
}

/// What kind of input a positional argument refers to.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum InputKind {
    Stdin,
    File(PathBuf),
}

/// The fully-resolved runtime configuration (CLI > env > config file > defaults
/// already merged). Produced by cli.rs, consumed by main.rs / printer.rs.
#[derive(Debug, Clone)]
pub struct Config {
    pub inputs: Vec<InputKind>,
    /// --file-name values, positionally mapped to `inputs` (None = use real name)
    pub file_names: Vec<Option<String>>,
    pub language: Option<String>,
    pub fallback_syntax: Option<String>,
    pub show_all: bool,
    pub nonprintable_notation: NonprintableNotation,
    pub binary: BinaryBehavior,
    pub highlight_lines: LineRanges,
    pub diff: bool,
    pub diff_context: Option<usize>,
    /// --tabs value; None if not given explicitly
    pub tabs: Option<usize>,
    pub wrap_mode: WrappingMode,
    /// resolved terminal width in columns
    pub terminal_width: usize,
    pub color: When,
    pub italic_text: ItalicWhen,
    pub decorations: When,
    pub paging: PagingMode,
    pub pager: Option<String>,
    pub map_syntax: Vec<(String, String)>,
    pub ignored_suffixes: Vec<String>,
    /// resolved theme name (after BAT_THEME/theme-dark/light resolution)
    pub theme_name: String,
    pub style_components: StyleComponents,
    pub line_ranges: LineRanges,
    pub squeeze_blank_lines: bool,
    pub squeeze_limit: Option<usize>,
    pub strip_ansi: StripAnsi,
    pub unbuffered: bool,
    pub quiet_empty: bool,
    pub set_terminal_title: bool,
    pub no_config: bool,

    // ---- resolved runtime facts ----
    /// stdout is an interactive terminal
    pub stdout_is_tty: bool,
    /// final decision: emit ANSI colors
    pub colored_output: bool,
    /// final decision: draw decorations
    pub decorations_active: bool,
    /// COLORTERM=truecolor|24bit (exact, lowercase)
    pub true_color: bool,
    /// basename of argv[0] (used in clap error usage lines)
    pub prog_name: String,
}

impl Config {
    /// The effective tab width used by the transforming printer.
    /// Default is 4 (even when --tabs 0 is NOT given; see specs/content.md).
    pub fn tab_width(&self) -> usize {
        self.tabs.unwrap_or(4)
    }
}

//! Theme data and ANSI emission. This file's PUBLIC API is FROZEN:
//! printer.rs and main.rs code against these signatures.
//! Color values per theme are probed from the reference binary
//! (see specs/colors-config.md, specs/styles.md, specs/content.md).

use std::io::Write;

/// A terminal color. `Rgb` is emitted as truecolor when enabled, otherwise
/// converted to the nearest xterm-256 index. `Ansi256` is always emitted as
/// `38;5;N` (even in truecolor mode). `Ansi4bit` is emitted as a plain
/// SGR code (e.g. 32 for green) — used for git change markers.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Color {
    Rgb(u8, u8, u8),
    Ansi256(u8),
    Ansi4bit(u8),
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct Style {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub bold: bool,
    pub italic: bool,
}

impl Style {
    pub const fn fg(c: Color) -> Self {
        Style { fg: Some(c), bg: None, bold: false, italic: false }
    }
    pub const fn plain() -> Self {
        Style { fg: None, bg: None, bold: false, italic: false }
    }
    pub const fn bold() -> Self {
        Style { fg: None, bg: None, bold: true, italic: false }
    }

    /// The SGR parameter list, e.g. "48;5;236;38;5;231" or "1".
    /// `true_color` selects 24-bit vs 256-color emission for Rgb colors.
    pub fn sgr_params(&self, true_color: bool) -> String {
        let mut parts: Vec<String> = Vec::new();
        if self.bold {
            parts.push("1".into());
        }
        if self.italic {
            parts.push("3".into());
        }
        if let Some(bg) = self.bg {
            parts.push(color_sgr(bg, true, true_color));
        }
        if let Some(fg) = self.fg {
            parts.push(color_sgr(fg, false, true_color));
        }
        parts.join(";")
    }

    /// Write `\e[<params>m<text>\e[0m`. If the style is completely empty,
    /// writes just the text.
    pub fn paint(&self, w: &mut dyn Write, text: &str, true_color: bool) -> std::io::Result<()> {
        if *self == Style::plain() {
            return w.write_all(text.as_bytes());
        }
        write!(w, "\x1b[{}m", self.sgr_params(true_color))?;
        w.write_all(text.as_bytes())?;
        w.write_all(b"\x1b[0m")
    }

    pub fn ansi_prefix(&self, true_color: bool) -> String {
        format!("\x1b[{}m", self.sgr_params(true_color))
    }
}

fn color_sgr(c: Color, background: bool, true_color: bool) -> String {
    match c {
        Color::Rgb(r, g, b) => {
            if true_color {
                format!("{};2;{};{};{}", if background { 48 } else { 38 }, r, g, b)
            } else {
                format!("{};5;{}", if background { 48 } else { 38 }, ansi256_from_rgb(r, g, b))
            }
        }
        Color::Ansi256(n) => format!("{};5;{}", if background { 48 } else { 38 }, n),
        Color::Ansi4bit(n) => format!("{}", if background { n + 10 } else { n }),
    }
}

/// Convert an RGB color to the nearest xterm-256 palette index.
/// Must match the algorithm the reference binary uses (see specs/colors-config.md;
/// validate against observed pairs like #839496->246, #f8f8f2->231, #66d9ef->81).
pub fn ansi256_from_rgb(r: u8, g: u8, b: u8) -> u8 {
    // Placeholder: naive cube+gray matching. THEME AGENT: replace with the exact
    // algorithm validated against observed conversions.
    let r = r as i32;
    let g = g as i32;
    let b = b as i32;
    let mut best = 0u8;
    let mut best_d = i64::MAX;
    for i in 0..=255u8 {
        let (pr, pg, pb) = palette_rgb(i);
        let d = ((r - pr as i32).pow(2) + (g - pg as i32).pow(2) + (b - pb as i32).pow(2)) as i64;
        if d < best_d {
            best_d = d;
            best = i;
        }
    }
    best
}

fn palette_rgb(i: u8) -> (u8, u8, u8) {
    const BASE: [(u8, u8, u8); 16] = [
        (0, 0, 0), (128, 0, 0), (0, 128, 0), (128, 128, 0),
        (0, 0, 128), (128, 0, 128), (0, 128, 128), (192, 192, 192),
        (128, 128, 128), (255, 0, 0), (0, 255, 0), (255, 255, 0),
        (0, 0, 255), (255, 0, 255), (0, 255, 255), (255, 255, 255),
    ];
    match i {
        0..=15 => BASE[i as usize],
        16..=231 => {
            let i = i - 16;
            let conv = |v: u8| if v == 0 { 0 } else { 55 + 40 * v };
            (conv(i / 36), conv((i % 36) / 6), conv(i % 6))
        }
        _ => {
            let v = 8 + 10 * (i - 232);
            (v, v, v)
        }
    }
}

/// The resolved set of colors used by the printer for a given theme.
/// All values probed from the reference binary (specs/colors-config.md).
#[derive(Debug, Clone)]
pub struct Theme {
    pub name: String,
    /// normal content foreground (plain text)
    pub foreground: Style,
    /// grid lines, line numbers, snip: the gray decoration color
    pub decoration: Style,
    /// background for --highlight-line
    pub highlight_bg: Color,
    // git change markers
    pub git_added: Style,
    pub git_modified: Style,
    pub git_deleted: Style,
    // -A/--show-all glyph colors (default = Monokai values from specs/content.md §5)
    pub np_tab: Style,
    pub np_newline: Style,
    pub np_cr: Style,
    pub np_space: Style,
    pub np_escape: Style,
    /// true if this theme leaves decorations uncolored (the 'ansi' theme)
    pub decorations_plain: bool,
}

impl Theme {
    /// Monokai Extended (the default dark theme) — probed values.
    pub fn monokai_extended() -> Self {
        Theme {
            name: "Monokai Extended".into(),
            foreground: Style::fg(Color::Rgb(0xf8, 0xf8, 0xf2)),
            decoration: Style::fg(Color::Rgb(0x83, 0x94, 0x96)),
            highlight_bg: Color::Rgb(0x3c, 0x3d, 0x37), // TODO: verify against 48;5;236
            git_added: Style::fg(Color::Ansi4bit(32)),
            git_modified: Style::fg(Color::Ansi4bit(33)),
            git_deleted: Style::fg(Color::Ansi4bit(31)),
            np_tab: Style::fg(Color::Ansi256(141)),
            np_newline: Style::fg(Color::Ansi256(203)),
            np_cr: Style::fg(Color::Ansi256(186)),
            np_space: Style::fg(Color::Ansi256(81)),
            np_escape: Style::fg(Color::Ansi256(242)),
            decorations_plain: false,
        }
    }
}
